"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1491],{78511:e=>{e.exports=JSON.parse('{"functions":[{"name":"AddXP","desc":"Award `amount` XP to a single player. No-op if amount <= 0 or the player\'s\\nprofile is not loaded. Fires `XPLevelUp` when the level increases, then\\nreplicates the new snapshot.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"amount","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":58,"path":"src/ServerStorage/SharedModules/XPManager.luau"}},{"name":"AddPartyXP","desc":"Award `amount` XP to every player in the server with a loaded profile.\\nXP is party-shared and one party occupies one server, so this is the\\nprimary award path for both kills and distance.","params":[{"name":"amount","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":82,"path":"src/ServerStorage/SharedModules/XPManager.luau"}},{"name":"Initialize","desc":"Wire up the profile lifecycle. Call exactly once per server (from a loader).","params":[],"returns":[],"function_type":"static","source":{"line":126,"path":"src/ServerStorage/SharedModules/XPManager.luau"}},{"name":"GetLevel","desc":"Current level for `player`, derived from stored TotalXP. Returns 1 if the\\nprofile is not loaded (safe default for point derivation).","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":161,"path":"src/ServerStorage/SharedModules/XPManager.luau"}}],"properties":[],"types":[],"name":"XPManager","desc":"Place-agnostic authority for player XP/Level. Owns the ProfileStore profile\\nlifecycle (one session per player, key = UserId), derives level/progress\\nfrom the single stored `TotalXP` via `XPCurve`, exposes the award API, and\\nreplicates state to the owning client via `XPStateSync` / `XPLevelUp`.\\n\\nRuns in BOTH the lobby and gameplay places. Earning sources (train distance,\\nenemy kills) live in the gameplay-only `XPSystemLoader`, not here.\\n\\nCross-place: `STORE_NAME` + `tostring(UserId)` key are identical in every\\nplace of the universe, so the same DataStore record is shared. ProfileStore\\nsession-locking serializes the lobby\u2194gameplay teleport handoff automatically.","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/XPManager.luau"}}')}}]);